// Get command output
const stdout = $input.first().json.stdout || "";
const stderr = $input.first().json.stderr || "";
const code = $input.first().json.code || 0;

// Check for errors
if (code !== 0) {
  return {
    json: {
      error: "Command failed",
      stderr: stderr,
      stdout: stdout,
      exitCode: code
    }
  };
}

// Parse JSON from stdout
let invoiceData;
try {
  // Try direct JSON parse
  invoiceData = JSON.parse(stdout);
} catch (error) {
  // Try to extract from markdown code block
  const jsonMatch = stdout.match(/```json\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    try {
      invoiceData = JSON.parse(jsonMatch[1]);
    } catch (e) {
      return {
        json: {
          error: "Could not parse JSON from code block",
          rawOutput: stdout,
          stderr: stderr
        }
      };
    }
  } else {
    // Try to find any JSON object in output
    const objMatch = stdout.match(/\{[\s\S]*\}/);
    if (objMatch) {
      try {
        invoiceData = JSON.parse(objMatch[0]);
      } catch (e) {
        return {
          json: {
            error: "Could not parse JSON object",
            rawOutput: stdout,
            stderr: stderr
          }
        };
      }
    } else {
      return {
        json: {
          error: "No JSON found in output",
          rawOutput: stdout,
          stderr: stderr
        }
      };
    }
  }
}

return {
  json: invoiceData
};
